node --input-type=module -e "
import { loadEnv, botToken } from './src/config.mjs';
import { writeFileSync } from 'node:fs';

const env = await loadEnv();
const tok = botToken(env);
if (!tok) { console.error('no token'); process.exit(1); }

const channelId = '1533603278816936168';
const headers = { Authorization: 'Bot ' + tok };

const msgsRes = await fetch('https://discord.com/api/v10/channels/' + channelId + '/messages?limit=30', { headers });
const msgs = await msgsRes.json();
if (!msgsRes.ok) {
  console.error('messages error', msgsRes.status, msgs);
  process.exit(1);
}

const chRes = await fetch('https://discord.com/api/v10/channels/' + channelId, { headers });
const ch = await chRes.json();

const slim = {
  channel: {
    id: ch.id,
    name: ch.name,
    type: ch.type,
    parent_id: ch.parent_id,
    owner_id: ch.owner_id,
    message_count: ch.message_count,
    total_message_sent: ch.total_message_sent,
  },
  messages: (Array.isArray(msgs) ? msgs : []).map(m => ({
    id: m.id,
    timestamp: m.timestamp,
    author: { id: m.author?.id, username: m.author?.username, bot: m.author?.bot, global_name: m.author?.global_name },
    content: m.content,
    referenced_message: m.referenced_message ? { id: m.referenced_message.id, author: m.referenced_message.author?.username, content: (m.referenced_message.content||'').slice(0,200) } : null,
    mentions: (m.mentions||[]).map(u => ({ id: u.id, username: u.username })),
    reactions: (m.reactions||[]).map(r => ({ emoji: r.emoji?.name || r.emoji?.id, count: r.count, me: r.me })),
  })),
};

writeFileSync('_tmp-boats-prop-thread.json', JSON.stringify(slim, null, 2));
console.log('ok', slim.messages.length, 'msgs; channel', slim.channel.name, 'type', slim.channel.type, 'parent', slim.channel.parent_id);
for (const m of slim.messages.slice().reverse()) {
  const who = m.author.global_name || m.author.username;
  console.log('---', m.timestamp, who, m.author.id, m.id);
  console.log((m.content||'').slice(0,500));
  if (m.reactions?.length) console.log('reactions:', JSON.stringify(m.reactions));
}
"

